solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <vector>

struct Cave { std::size_t offset; std::size_t length; };

std::vector<Cave> findCaves(const std::vector<std::uint8_t>& code, std::size_t minLength)
{
    std::vector<Cave> caves;
    std::size_t i{ 0 };
    while (i < code.size())
    {
        const std::uint8_t b{ code[i] };
        if (b != 0x00 && b != 0xCC) { ++i; continue; }
        const std::size_t start{ i };
        while (i < code.size() && code[i] == b) ++i;
        if (i - start >= minLength) caves.push_back({ start, i - start });
    }
    return caves;
}

std::optional<std::size_t> bytesToSteal(const std::vector<std::size_t>& instructionLengths, std::size_t needed)
{
    std::size_t total{ 0 };
    for (std::size_t length : instructionLengths)
    {
        if (total >= needed) break;
        total += length;
    }
    if (total < needed) return std::nullopt;
    return total;
}

std::optional<std::vector<std::uint8_t>> buildCave(const std::vector<std::uint8_t>& stolen, const std::vector<std::uint8_t>& newCode,
                                                    std::uint64_t caveAddress, std::uint64_t returnAddress)
{
    if (!stolen.empty())
    {
        const std::uint8_t first{ stolen[0] };
        const bool relative{ first == 0xE8 || first == 0xE9 || first == 0xEB || (first >= 0x70 && first <= 0x7F)
                             || (first == 0x0F && stolen.size() > 1 && stolen[1] >= 0x80 && stolen[1] <= 0x8F) };
        if (relative) return std::nullopt;
    }
    std::vector<std::uint8_t> cave{ newCode };
    cave.insert(cave.end(), stolen.begin(), stolen.end());
    const std::uint64_t jumpAt{ caveAddress + cave.size() };
    const auto disp{ static_cast<std::int64_t>(returnAddress - (jumpAt + 5)) };
    if (disp < INT32_MIN || disp > INT32_MAX) return std::nullopt;
    cave.push_back(0xE9);
    const auto u{ static_cast<std::uint32_t>(static_cast<std::int32_t>(disp)) };
    for (int i{ 0 }; i < 4; ++i) cave.push_back(static_cast<std::uint8_t>(u >> (8 * i)));
    return cave;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("finding caves") {
    Bytes code{ 0xC3, 0xCC, 0xCC, 0xCC, 0xCC, 0xCC, 0x48, 0x00, 0x00, 0xCC, 0xCC, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 };
    const auto caves{ findCaves(code, 4) };
    CHECK_EQ(caves.size(), 2u);
    if (caves.size() == 2) { CHECK_EQ(caves[0].offset, 1u); CHECK_EQ(caves[0].length, 5u); CHECK_EQ(caves[1].offset, 11u); CHECK_EQ(caves[1].length, 6u); }
    CHECK_EQ(findCaves(code, 2).size(), 4u);
    CHECK(findCaves(code, 7).empty());
}
TEST("bytes to steal") {
    CHECK_EQ(bytesToSteal({ 3, 2, 3 }, 5).value_or(0), 5u);
    CHECK_EQ(bytesToSteal({ 2, 2, 4, 1 }, 5).value_or(0), 8u);
    CHECK_EQ(bytesToSteal({ 7 }, 5).value_or(0), 7u);
    CHECK_EQ(bytesToSteal({ 5, 5 }, 14).value_or(0), 0u);
    CHECK_EQ(bytesToSteal({ 4, 4, 4, 4 }, 14).value_or(0), 16u);
}
TEST("building the cave") {
    const Bytes stolen{ 0x8B, 0x47, 0x1C, 0x2B, 0xC3 };
    const Bytes logging{ 0x90 };
    const auto cave{ buildCave(stolen, logging, 0x140009000, 0x140001A35) };
    CHECK(cave.has_value());
    if (!cave) return;
    CHECK_EQ(cave->size(), 11u);
    CHECK((*cave)[0] == 0x90);
    CHECK((*cave)[1] == 0x8B && (*cave)[5] == 0xC3);
    CHECK((*cave)[6] == 0xE9);
    CHECK(Bytes(cave->begin() + 7, cave->end()) == (Bytes{ 0x2A, 0x8A, 0xFF, 0xFF }));
}
TEST("refusing to copy relative instructions") {
    CHECK(!buildCave({ 0xE8, 1, 2, 3, 4 }, {}, 0x1000, 0x2000).has_value());
    CHECK(!buildCave({ 0x74, 0x05, 0x90 }, {}, 0x1000, 0x2000).has_value());
    CHECK(!buildCave({ 0x0F, 0x84, 0, 0, 0, 0 }, {}, 0x1000, 0x2000).has_value());
    CHECK(!buildCave({ 0x90 }, {}, 0x7FF600000000, 0x1000).has_value());
    CHECK(buildCave({ 0x0F, 0x1F, 0x00 }, {}, 0x1000, 0x2000).has_value());
}

